<?php session_start(); if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Map · MBUS</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><link rel="stylesheet" href="../Assets/css/bottom-nav.css"><link rel="stylesheet" href="../Assets/css/app-header.css"><style>body{font-family:Inter,system-ui;background:#f6f8fb;color:#162033;margin:0}.wrap{max-width:900px;margin:auto;padding:1.25rem 1rem 7rem}.card{background:#fff;border:1px solid #e5eaf1;border-radius:18px;padding:1rem;margin:1rem 0}.map{height:420px;border-radius:16px;background:linear-gradient(135deg,#dbeafe,#ecfeff);display:grid;place-items:center;color:#285f8f}.bus{display:flex;justify-content:space-between;gap:1rem;padding:.8rem 0;border-bottom:1px solid #edf1f5}.muted{color:#65748a}</style></head><body><main class="wrap"><h1><i class="fa fa-map-location-dot"></i> Live map</h1><p class="muted">See recently active buses and their current operating status. Locations refresh automatically.</p><section class="card"><div id="map" class="map">Live map loading…</div></section><section class="card"><h2>Active buses</h2><div id="buses">Loading…</div></section></main><nav class="bottom-nav"><a href="commuter_dashboard.php" class="bottom-nav-item"><i class="fa fa-home"></i><span>Home</span></a><a href="schedule.php" class="bottom-nav-item"><i class="fa fa-calendar"></i><span>Schedule</span></a><a href="live_map.php" class="bottom-nav-item active"><i class="fa fa-map-location-dot"></i><span>Live</span></a><a href="my_reservations.php" class="bottom-nav-item"><i class="fa fa-ticket"></i><span>Trips</span></a><a href="notifications.php" class="bottom-nav-item"><i class="fa fa-bell"></i><span>Alerts</span></a></nav><script>async function refresh(){const r=await fetch('../api/get_live_map_data.php',{cache:'no-store'});const j=await r.json();const el=document.getElementById('buses');el.innerHTML=j.buses?.length?j.buses.map(b=>`<div class="bus"><span><strong>Bus ${b.bus_number}</strong><br><small>${b.origin||'Route'} → ${b.destination||''}</small></span><span>${b.trip_status||'Live'}<br><small>${b.waiting_count||0} waiting</small></span></div>`).join(''):'<p class="muted">No recent bus locations.</p>';if(j.buses?.length)document.getElementById('map').innerHTML='<i class="fa fa-location-dot"></i> '+j.buses.length+' bus location(s) available';}refresh();setInterval(refresh,15000);</script></body></html>
